package com.acme.agri.alerts;

import java.time.Instant;

/**
 * Raises a low-moisture alert when the latest reading is below the field's threshold.
 */
public class SoilMoistureAlertRule {

    private final SensorReadingRepository readings;
    private final ThresholdRepository thresholds;
    private final AlertPublisher publisher;

    public SoilMoistureAlertRule(SensorReadingRepository readings, ThresholdRepository thresholds, AlertPublisher publisher) {
        this.readings = readings;
        this.thresholds = thresholds;
        this.publisher = publisher;
    }

    public void evaluate(String fieldId, Instant now) {
        double latest = readings.latestFor(fieldId, SensorKind.SOIL_MOISTURE);
        double minimum = thresholds.minSoilMoisture(fieldId);
        if (latest < minimum) {
            publisher.publish(new Alert(fieldId, "SOIL_MOISTURE_LOW", latest, minimum, now));
        }
    }
}

