/** Raises an alert when a sensor has not reported within its stale window. */
public class StaleSensorAlertRule {
    private final SensorReadingRepository readings;
    private final AlertPublisher publisher;

    public StaleSensorAlertRule(SensorReadingRepository readings, AlertPublisher publisher) {
        this.readings = readings;
        this.publisher = publisher;
    }

    public void evaluate(String sensorId, java.time.Duration staleAfter, Instant now) {
        Instant last = readings.lastReportedAt(sensorId);
        if (last.isBefore(now.minus(staleAfter))) {
            publisher.publish(new Alert(sensorId, "SENSOR_STALE", last, staleAfter.toMinutes(), now));
        }
    }
