package com.acme.agri.analytics;

import java.time.Duration;
import java.time.Instant;
import java.util.List;

/**
 * Computes average soil moisture over a window, skipping faulty readings.
 */
public class AverageSoilMoistureCalculator {

    private final SensorReadingRepository readings;

    public AverageSoilMoistureCalculator(SensorReadingRepository readings) {
        this.readings = readings;
    }

    public double average(String fieldId, Instant from, Instant to) {
        List<SensorReading> window = readings.findBetween(fieldId, SensorKind.SOIL_MOISTURE, from, to);
        double sum = 0.0;
        int count = 0;
        for (SensorReading r : window) {
            if (r.isFaulty()) continue;
            sum += r.getValue();
            count++;
        }
        if (count == 0) {
            throw new NoReadingsException(fieldId, from, to);
        }
        return sum / count;
    }
}

