package com.acme.agri.ingest;

import java.time.Instant;

/**
 * Ingests a sensor reading, validates range, persists and refreshes cache.
 */
public class ReadingIngestService {

    private final SensorRepository sensors;
    private final SensorReadingRepository readings;
    private final LatestReadingCache cache;

    public ReadingIngestService(SensorRepository sensors, SensorReadingRepository readings, LatestReadingCache cache) {
        this.sensors = sensors;
        this.readings = readings;
        this.cache = cache;
    }

    public SensorReading ingest(String sensorId, double value, Instant reportedAt) {
        Sensor s = sensors.require(sensorId);
        if (value < s.getMinValue() || value > s.getMaxValue()) {
            throw new OutOfRangeReadingException(sensorId, value, s.getMinValue(), s.getMaxValue());
        }
        SensorReading saved = readings.save(new SensorReading(sensorId, s.getKind(), value, reportedAt, false));
        cache.update(sensorId, saved);
        return saved;
    }
}

