package com.acme.agri.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an audit row on each configuration change.
 */
public class ConfigurationChangeAuditor {

    private final EntityManager em;

    public ConfigurationChangeAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String entityType, String entityId, String field, String oldValue, String newValue, String actorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            ConfigAuditEntry e = new ConfigAuditEntry();
            e.setEntityType(entityType);
            e.setEntityId(entityId);
            e.setField(field);
            e.setOldValue(oldValue);
            e.setNewValue(newValue);
            e.setActorId(actorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

