/* daily_field_summary.c - write daily field moisture summary as CSV */
#include <stdio.h>
#include "agri_db.h"

int write_daily_field_summary(const char *day, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "field_id,min_moisture,max_moisture,avg_moisture,readings_count\n");

    db_cursor_t *cur = NULL;
    if (db_open_daily_moisture_cursor(&cur, day) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    field_moisture_row_t row;
    while (db_moisture_cursor_next(cur, &row) == DB_OK) {
        if (row.faulty_count == row.readings_count) continue;
        fprintf(out, "%s,%.2f,%.2f,%.2f,%d\n",
                row.field_id, row.min_moisture, row.max_moisture,
                row.avg_moisture, row.readings_count - row.faulty_count);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

